// OTOMATİK ÜRETİLDİ: research/eval/final_model.py. Elle düzenleme.
// Gradyan artırmalı karar ağaçları (scikit-learn HistGradientBoosting). Yayın modeli: yalnızca Svanström (CC0) ve ESC-10 (CC BY) verileriyle eğitildi.
import 'dart:math' as math;

import 'detector.dart';

class GbmTree {
  const GbmTree(this.f, this.t, this.l, this.r, this.leaf, this.v);
  final List<int> f, l, r, leaf;
  final List<double> t, v;
}

class DetectorModel {
  const DetectorModel({required this.features, required this.fill, required this.logFloor, required this.base, required this.trees, this.reasonThresholds = const {}});
  final List<String> features;
  final List<double> fill;
  final List<double> logFloor;
  final double base;
  final List<GbmTree> trees;
  final Map<String, double> reasonThresholds;

  /// Penceredeki özelliklerden drone olasılığı.
  double predict(Aggregate agg) {
    final x = List<double>.filled(features.length, 0);
    for (var i = 0; i < features.length; i++) {
      var v = agg.feature(features[i]);
      if (!v.isFinite) v = fill[i];
      if (logFloor[i] > 0) v = math.log(math.max(v, logFloor[i])) / math.ln10;
      x[i] = v;
    }
    var raw = base;
    for (final tr in trees) {
      var n = 0;
      while (tr.leaf[n] == 0) {
        n = x[tr.f[n]] <= tr.t[n] ? tr.l[n] : tr.r[n];
      }
      raw += tr.v[n];
    }
    return 1 / (1 + math.exp(-raw));
  }
}

